    // Key flow — A / C

    TwistExpander_Bellatrix_Arx::KEY_A_C_A(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_A_C_B(PARAMS_SEED);

    KeyDiffuse_A_A_C(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_A_C_C(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_A_C_D(PARAMS_SEED);

    KeyDiffuse_B_A_C(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_A_C_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(BELLATRIX_KEY_A_C_IceLaneA, BELLATRIX_KEY_A_C_IceLaneB, BELLATRIX_KEY_A_C_IceLaneC, BELLATRIX_KEY_A_C_IceLaneD, &(pWorkSpace->mKeyBoxA[2U][0]));

    // Key flow — A / D

    TwistExpander_Bellatrix_Arx::KEY_A_D_A(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_A_D_B(PARAMS_SEED);

    KeyDiffuse_A_A_D(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_A_D_C(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_A_D_D(PARAMS_SEED);

    KeyDiffuse_B_A_D(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_A_D_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(BELLATRIX_KEY_A_D_IceLaneA, BELLATRIX_KEY_A_D_IceLaneB, BELLATRIX_KEY_A_D_IceLaneC, BELLATRIX_KEY_A_D_IceLaneD, &(pWorkSpace->mKeyBoxA[3U][0]));

    // Key flow — A / E

    TwistExpander_Bellatrix_Arx::KEY_A_E_A(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_A_E_B(PARAMS_SEED);

    KeyDiffuse_A_A_E(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_A_E_C(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_A_E_D(PARAMS_SEED);

    KeyDiffuse_B_A_E(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_A_E_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(BELLATRIX_KEY_A_E_IceLaneA, BELLATRIX_KEY_A_E_IceLaneB, BELLATRIX_KEY_A_E_IceLaneC, BELLATRIX_KEY_A_E_IceLaneD, &(pWorkSpace->mKeyBoxA[4U][0]));

    // Key flow — A / F

    TwistExpander_Bellatrix_Arx::KEY_A_F_A(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_A_F_B(PARAMS_SEED);

    KeyDiffuse_A_A_F(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_A_F_C(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_A_F_D(PARAMS_SEED);

    KeyDiffuse_B_A_F(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_A_F_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(BELLATRIX_KEY_A_F_IceLaneA, BELLATRIX_KEY_A_F_IceLaneB, BELLATRIX_KEY_A_F_IceLaneC, BELLATRIX_KEY_A_F_IceLaneD, &(pWorkSpace->mKeyBoxA[5U][0]));

    // Key flow — A / G

    TwistExpander_Bellatrix_Arx::KEY_A_G_A(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_A_G_B(PARAMS_SEED);

    KeyDiffuse_A_A_G(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_A_G_C(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_A_G_D(PARAMS_SEED);

    KeyDiffuse_B_A_G(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_A_G_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(BELLATRIX_KEY_A_G_IceLaneA, BELLATRIX_KEY_A_G_IceLaneB, BELLATRIX_KEY_A_G_IceLaneC, BELLATRIX_KEY_A_G_IceLaneD, &(pWorkSpace->mKeyBoxA[6U][0]));

    // Key flow — A / H

    TwistExpander_Bellatrix_Arx::KEY_A_H_A(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_A_H_B(PARAMS_SEED);

    KeyDiffuse_A_A_H(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_A_H_C(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_A_H_D(PARAMS_SEED);

    KeyDiffuse_B_A_H(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_A_H_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(BELLATRIX_KEY_A_H_IceLaneA, BELLATRIX_KEY_A_H_IceLaneB, BELLATRIX_KEY_A_H_IceLaneC, BELLATRIX_KEY_A_H_IceLaneD, &(pWorkSpace->mKeyBoxA[7U][0]));

    // Key flow — B / A

    TwistExpander_Bellatrix_Arx::KEY_B_A_A(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_B_A_B(PARAMS_SEED);

    KeyDiffuse_A_B_A(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_B_A_C(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_B_A_D(PARAMS_SEED);

