    // Key flow — B / B

    TwistExpander_Bellatrix_Arx::KEY_B_B_A(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_B_B_B(PARAMS_SEED);

    KeyDiffuse_A_B_B(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_B_B_C(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_B_B_D(PARAMS_SEED);

