    TwistExpander_Bellatrix_Arx::KEY_B_B_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(BELLATRIX_KEY_B_B_IceLaneA, BELLATRIX_KEY_B_B_IceLaneB, BELLATRIX_KEY_B_B_IceLaneC, BELLATRIX_KEY_B_B_IceLaneD, &(pWorkSpace->mKeyBoxB[1U][0]));

    // Key flow — B / C

    TwistExpander_Bellatrix_Arx::KEY_B_C_A(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_B_C_B(PARAMS_SEED);

    KeyDiffuse_A_B_C(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_B_C_C(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_B_C_D(PARAMS_SEED);

    KeyDiffuse_B_B_C(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_B_C_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(BELLATRIX_KEY_B_C_IceLaneA, BELLATRIX_KEY_B_C_IceLaneB, BELLATRIX_KEY_B_C_IceLaneC, BELLATRIX_KEY_B_C_IceLaneD, &(pWorkSpace->mKeyBoxB[2U][0]));

    // Key flow — B / D

    TwistExpander_Bellatrix_Arx::KEY_B_D_A(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_B_D_B(PARAMS_SEED);

    KeyDiffuse_A_B_D(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_B_D_C(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_B_D_D(PARAMS_SEED);

    KeyDiffuse_B_B_D(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_B_D_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(BELLATRIX_KEY_B_D_IceLaneA, BELLATRIX_KEY_B_D_IceLaneB, BELLATRIX_KEY_B_D_IceLaneC, BELLATRIX_KEY_B_D_IceLaneD, &(pWorkSpace->mKeyBoxB[3U][0]));

    // Key flow — B / E

    TwistExpander_Bellatrix_Arx::KEY_B_E_A(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_B_E_B(PARAMS_SEED);

