    TwistExpander_Bellatrix_Arx::KEY_B_E_C(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_B_E_D(PARAMS_SEED);

    KeyDiffuse_B_B_E(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_B_E_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(BELLATRIX_KEY_B_E_IceLaneA, BELLATRIX_KEY_B_E_IceLaneB, BELLATRIX_KEY_B_E_IceLaneC, BELLATRIX_KEY_B_E_IceLaneD, &(pWorkSpace->mKeyBoxB[4U][0]));

    // Key flow — B / F

    TwistExpander_Bellatrix_Arx::KEY_B_F_A(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_B_F_B(PARAMS_SEED);

