    TwistExpander_Bellatrix_Arx::KEY_B_F_C(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::KEY_B_F_D(PARAMS_SEED);

    KeyDiffuse_B_B_F(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_B_F_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(BELLATRIX_KEY_B_F_IceLaneA, BELLATRIX_KEY_B_F_IceLaneB, BELLATRIX_KEY_B_F_IceLaneC, BELLATRIX_KEY_B_F_IceLaneD, &(pWorkSpace->mKeyBoxB[5U][0]));

    // Key flow — B / G

    TwistExpander_Bellatrix_Arx::KEY_B_G_A(PARAMS_SEED);

