    TwistExpander_Bellatrix_Arx::KEY_B_G_D(PARAMS_SEED);

    KeyDiffuse_B_B_G(pWorkSpace);

    TwistExpander_Bellatrix_Arx::KEY_B_G_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(BELLATRIX_KEY_B_G_IceLaneA, BELLATRIX_KEY_B_G_IceLaneB, BELLATRIX_KEY_B_G_IceLaneC, BELLATRIX_KEY_B_G_IceLaneD, &(pWorkSpace->mKeyBoxB[6U][0]));

    // Key flow — B / H

    TwistExpander_Bellatrix_Arx::KEY_B_H_A(PARAMS_SEED);

