    TwistSquash::SquashKeyA(BELLATRIX_KEY_B_H_IceLaneA, BELLATRIX_KEY_B_H_IceLaneB, BELLATRIX_KEY_B_H_IceLaneC, BELLATRIX_KEY_B_H_IceLaneD, &(pWorkSpace->mKeyBoxB[7U][0]));

